def mecca_map(w,h,title,labels,cap):
    b=f'<rect x="5" y="5" width="{w-10}" height="{h-10}" fill="#fff" stroke="#111" stroke-width="2"/>'+T(w-70,38,title,17,'middle',700)
    b+='<ellipse cx="220" cy="200" rx="105" ry="135" fill="none" stroke="#555" stroke-width="3" stroke-dasharray="2 3"/><ellipse cx="220" cy="200" rx="55" ry="85" fill="none" stroke="#555" stroke-dasharray="2 3"/>'
    b+='<ellipse cx="200" cy="395" rx="55" ry="75" fill="none" stroke="#555" stroke-width="3" stroke-dasharray="2 3"/>'
    b+='<path d="M240 400 L330 360 L360 430 L300 500 L210 520 L170 470Z" fill="#ddd" stroke="#555" stroke-width="2"/>'
    b+='<path d="M60 120 L120 60 L300 80 L400 150" fill="none" stroke="#111" stroke-width="2" stroke-dasharray="8 3 2 3"/>'
    b+='<path d="M60 350 L180 345 L280 320" fill="none" stroke="#111" stroke-width="2" stroke-dasharray="8 3 2 3"/>'
    b+='<path d="M100 440 L200 470" fill="none" stroke="#111" stroke-width="2" stroke-dasharray="8 3 2 3"/>'
    b+='<path d="M215 540 L190 590" fill="none" stroke="#111" stroke-width="2" stroke-dasharray="8 3 2 3"/>'
    b+='<g stroke="#111" stroke-width="2" fill="none"><path d="M70 200 L70 120"/><path d="M64 128 L70 118 L76 128"/></g>'
    for x,y,t in labels: b+=T(x,y,t,11,'middle',700)
    b+='<rect x="20" y="'+str(h-110)+'" width="130" height="95" fill="#fff" stroke="#111"/><line x1="30" y1="'+str(h-90)+'" x2="60" y2="'+str(h-90)+'" stroke="#555" stroke-width="3"/><rect x="30" y="'+str(h-75)+'" width="30" height="12" fill="#ccc" stroke="#555"/><line x1="30" y1="'+str(h-50)+'" x2="60" y2="'+str(h-50)+'" stroke="#111" stroke-dasharray="8 3"/><line x1="30" y1="'+str(h-30)+'" x2="60" y2="'+str(h-30)+'" stroke="#111" stroke-width="2"/>'
    b+=T(105,h-87,'پہاڑ',11,'middle',700)+T(105,h-65,'آبادی',11,'middle',700)+T(105,h-46,'راستہ',11,'middle',700)+T(105,h-26,'فوجوں کی حرکت کی سمت',10,'middle',700)
    return svg(w,h,cap,b)
